EQUATIONS.phases="<div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi mathvariant=\"normal\">F</mi><msub><mi mathvariant=\"normal\">e</mi><mn>3</mn></msub><msub><mi mathvariant=\"normal\">O</mi><mn>4</mn></msub></mrow><mo>:</mo><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mrow><mi mathvariant=\"normal\">F</mi><msup><mi mathvariant=\"normal\">e</mi><mrow><mn>3</mn><mo>+</mo></mrow></msup></mrow><msub><mo stretchy=\"false\">)</mo><mi>A</mi></msub><mo stretchy=\"false\">[</mo><mrow><mi mathvariant=\"normal\">F</mi><msup><mi mathvariant=\"normal\">e</mi><mrow><mn>2</mn><mo>+</mo></mrow></msup><mi mathvariant=\"normal\">F</mi><msup><mi mathvariant=\"normal\">e</mi><mrow><mn>3</mn><mo>+</mo></mrow></msup></mrow><msub><mo stretchy=\"false\">]</mo><mi>B</mi></msub><msub><mi mathvariant=\"normal\">O</mi><mn>4</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\mathrm{Fe_3O_4}:\\quad(\\mathrm{Fe^{3+}})_{A}[\\mathrm{Fe^{2+}Fe^{3+}}]_{B}\\mathrm O_4</annotation></semantics></math></span></div><div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>γ</mi><mtext>-</mtext><mrow><mi mathvariant=\"normal\">F</mi><msub><mi mathvariant=\"normal\">e</mi><mn>2</mn></msub><msub><mi mathvariant=\"normal\">O</mi><mn>3</mn></msub></mrow><mo>:</mo><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mrow><mi mathvariant=\"normal\">F</mi><msup><mi mathvariant=\"normal\">e</mi><mrow><mn>3</mn><mo>+</mo></mrow></msup></mrow><msub><mo stretchy=\"false\">)</mo><mi>A</mi></msub><mo stretchy=\"false\">[</mo><mrow><mi mathvariant=\"normal\">F</mi><msubsup><mi mathvariant=\"normal\">e</mi><mrow><mn>5</mn><mi mathvariant=\"normal\">/</mi><mn>3</mn></mrow><mrow><mn>3</mn><mo>+</mo></mrow></msubsup></mrow><mtext> </mtext><msub><mi mathvariant=\"normal\">□</mi><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>3</mn></mrow></msub><msub><mo stretchy=\"false\">]</mo><mi>B</mi></msub><msub><mi mathvariant=\"normal\">O</mi><mn>4</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\gamma\\text{-}\\mathrm{Fe_2O_3}:\\quad(\\mathrm{Fe^{3+}})_{A}[\\mathrm{Fe^{3+}_{5/3}}\\,\\square_{1/3}]_{B}\\mathrm O_4</annotation></semantics></math></span></div>";
