Object.assign(EQUATIONS,{"relaxivity":"<div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mi>i</mi></msub><mo>=</mo><msub><mi>R</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mn>0</mn></mrow></msub><mo>+</mo><msub><mi>r</mi><mi>i</mi></msub><msub><mi>c</mi><mrow><mi mathvariant=\"normal\">F</mi><mi mathvariant=\"normal\">e</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">R_i=R_{i,0}+r_i c_{\\mathrm{Fe}}</annotation></semantics></math></span></div><div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>τ</mi><mi>D</mi></msub><mo>=</mo><mfrac><msup><mi>d</mi><mn>2</mn></msup><mrow><mn>4</mn><mi>D</mi></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">Δ</mi><mi>ω</mi><mo>=</mo><mfrac><mrow><mi>γ</mi><msub><mi>μ</mi><mn>0</mn></msub><msub><mi>M</mi><mi>v</mi></msub></mrow><mn>3</mn></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">Δ</mi><mi>ω</mi><msub><mi>τ</mi><mi>D</mi></msub><mo>&lt;</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\tau_D=\\frac{d^2}{4D},\\qquad\\Delta\\omega=\\frac{\\gamma\\mu_0M_v}{3},\\qquad\\Delta\\omega\\tau_D&lt;1</annotation></semantics></math></span></div><div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mfrac><mrow><msub><mi>r</mi><mn>2</mn></msub><msub><mi>ϕ</mi><mrow><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">t</mi><mi mathvariant=\"normal\">r</mi><mi mathvariant=\"normal\">a</mi></mrow></msub></mrow><msubsup><mi>M</mi><mi>v</mi><mn>2</mn></msubsup></mfrac><mo>∝</mo><mfrac><msup><mi>d</mi><mn>2</mn></msup><mi>D</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\frac{r_2\\phi_{\\mathrm{intra}}}{M_v^2}\\propto\\frac{d^2}{D}</annotation></semantics></math></span></div>","forc":"<div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mfrac><mi>M</mi><msub><mi>M</mi><mi>s</mi></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>ρ</mi><mo stretchy=\"false\">(</mo><mi>H</mi><mo separator=\"true\">,</mo><msub><mi>H</mi><mi>r</mi></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mfrac><mrow><msup><mi mathvariant=\"normal\">∂</mi><mn>2</mn></msup><mi>m</mi><mo stretchy=\"false\">(</mo><mi>H</mi><mo separator=\"true\">,</mo><msub><mi>H</mi><mi>r</mi></msub><mo stretchy=\"false\">)</mo></mrow><mrow><mi mathvariant=\"normal\">∂</mi><mi>H</mi><mtext> </mtext><mi mathvariant=\"normal\">∂</mi><msub><mi>H</mi><mi>r</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">m=\\frac{M}{M_s},\\qquad\\rho(H,H_r)=-\\frac12\\frac{\\partial^2 m(H,H_r)}{\\partial H\\,\\partial H_r}</annotation></semantics></math></span></div><div class=\"equation-line\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>H</mi><mi>c</mi></msub><mo>=</mo><mfrac><mrow><mi>H</mi><mo>−</mo><msub><mi>H</mi><mi>r</mi></msub></mrow><mn>2</mn></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>H</mi><mi>u</mi></msub><mo>=</mo><mfrac><mrow><mi>H</mi><mo>+</mo><msub><mi>H</mi><mi>r</mi></msub></mrow><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">H_c=\\frac{H-H_r}{2},\\qquad H_u=\\frac{H+H_r}{2}</annotation></semantics></math></span></div>"});
const D={"phases":{"a":0,"kind":"reading","static":true,"n":["Oxydes de fer : phases et sites","Iron oxides: phases and sites"],"lead":["La composition et l’occupation des sites relient la structure cristalline aux propriétés magnétiques.","Composition and site occupancy connect crystal structure with magnetic properties."],"body":["<div class=\"text-module\"><h3>Deux oxydes à structure spinelle</h3><p>Les oxygènes entourent deux familles de sites du fer. Les sites A sont tétraédriques : quatre oxygènes entourent le cation. Les sites B sont octaédriques : six oxygènes l’entourent.</p><div class=\"phase-table\"><table><thead><tr><th>Composition idéale</th><th>Magnétite · Fe₃O₄</th><th>Maghémite · γ-Fe₂O₃</th></tr></thead><tbody><tr><th>Sites A</th><td>Fe³⁺</td><td>Fe³⁺</td></tr><tr><th>Sites B</th><td>Fe²⁺ + Fe³⁺</td><td>5/3 Fe³⁺ + 1/3 lacune</td></tr><tr><th>Normalisation</th><td>3 Fe pour 4 O</td><td>8/3 Fe pour 4 O</td></tr><tr><th>Lacunes cationiques idéales</th><td>Aucune</td><td>1/6 des sites B</td></tr></tbody></table></div><p>La magnétite est une spinelle inverse. À température ambiante, les sites B portent une valence moyenne mixte. La notation Fe²⁺/Fe³⁺ compte les charges ; elle ne fixe pas deux positions immobiles distinctes. L’oxydation vers la maghémite supprime le Fe²⁺ et crée des lacunes cationiques.</p><h3>Du cristal au ferrimagnétisme</h3><p>Les moments des sous-réseaux A et B sont opposés. Ils ne se compensent pas. Il subsiste un moment résultant : c’est le ferrimagnétisme. <a class=\"data-cite\" href=\"https://goldbook.iupac.org/terms/view/M03690\" target=\"_blank\" rel=\"noopener noreferrer\">IUPAC M03690</a></p><p>Le modèle ionique colinéaire donne 4 μB par Fe₃O₄ pour la magnétite et 10/3 μB par Fe₈/₃O₄ pour la maghémite. Ces bilans utilisent Fe³⁺ haut spin : 5 μB, et Fe²⁺ haut spin : 4 μB. L’aimantation mesurée dépend aussi de la température, des défauts et des surfaces.</p><details><summary>Voir les coordinations issues des coordonnées cristallines</summary><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 390\" role=\"img\" aria-label=\"Coordinations du fer dans la magnétite\"><defs><radialGradient id=\"oxygenPhase\"><stop stop-color=\"#f8e2dd\"/><stop offset=\"1\" stop-color=\"#be6a5f\"/></radialGradient><radialGradient id=\"ironPhase\"><stop stop-color=\"#c6dceb\"/><stop offset=\"1\" stop-color=\"#31579c\"/></radialGradient></defs><path d=\"M201.7 281.9L145.7 138.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M201.7 281.9L304.3 180.5\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M201.7 281.9L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M145.7 138.6L304.3 180.5\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M145.7 138.6L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M304.3 180.5L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M225 185L201.7 281.9\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L145.7 138.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L304.3 180.5\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L248.3 139.1\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><circle cx=\"304.3\" cy=\"180.5\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"304.3\" y=\"185.5\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"145.7\" cy=\"138.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"145.7\" y=\"143.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"225.0\" cy=\"185.0\" r=\"22\" fill=\"url(#ironPhase)\"/><text x=\"225.0\" y=\"190.0\" text-anchor=\"middle\" fill=\"white\" font-size=\"14\">Fe</text><circle cx=\"201.7\" cy=\"281.9\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"201.7\" y=\"286.9\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"248.3\" cy=\"139.1\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"248.3\" y=\"144.1\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><text x=\"225\" y=\"48\" text-anchor=\"middle\" font-size=\"21\" fill=\"#243944\">Site A · tétraédrique</text><text x=\"225\" y=\"330\" text-anchor=\"middle\" font-size=\"17\" fill=\"#243944\">Fe–O ≈ 1.889 Å · 4 O</text><path d=\"M579.3 233.4L725.9 272.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L674.1 139.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L675.9 230.4\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L674.1 139.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L675.9 230.4\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M674.1 139.6L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M674.1 139.6L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675.9 230.4L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675.9 230.4L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M624.1 97.9L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675 185L579.3 233.4\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L725.9 272.1\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L674.1 139.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L675.9 230.4\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L624.1 97.9\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L770.7 136.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><circle cx=\"674.1\" cy=\"139.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"674.1\" y=\"144.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"725.9\" cy=\"272.1\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"725.9\" y=\"277.1\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"579.3\" cy=\"233.4\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"579.3\" y=\"238.4\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"675.0\" cy=\"185.0\" r=\"22\" fill=\"url(#ironPhase)\"/><text x=\"675.0\" y=\"190.0\" text-anchor=\"middle\" fill=\"white\" font-size=\"14\">Fe</text><circle cx=\"770.7\" cy=\"136.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"770.7\" y=\"141.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"624.1\" cy=\"97.9\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"624.1\" y=\"102.9\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"675.9\" cy=\"230.4\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"675.9\" y=\"235.4\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><text x=\"675\" y=\"48\" text-anchor=\"middle\" font-size=\"21\" fill=\"#243944\">Site B · octaédrique</text><text x=\"675\" y=\"330\" text-anchor=\"middle\" font-size=\"17\" fill=\"#243944\">Fe–O ≈ 2.058 Å · 6 O</text></svg><p>Voisins oxygène et distances calculés à partir du CIF de la magnétite. Les polyèdres sont orientés pour être lisibles. <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9007644.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9007644 · Fleet, 1981</a></p></details><details><summary>Symétrie, paramètres de maille et identification</summary><p>Magnétite : Fd3̅m, a = 8,3941 Å dans l’entrée <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9007644.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9007644 · Fleet, 1981</a>. La maille conventionnelle contient 8 sites A, 16 sites B et 32 oxygènes.</p><p>Maghémite : l’entrée <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9017489.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9017489 · Shmakov et al., 1995</a> décrit une structure cubique P4₃32 avec a = 8,3474 Å. L’ordre des lacunes peut conduire à d’autres symétries, notamment une superstructure tétragonale. Le modèle avec lacunes sur B est une référence idéale ; les nanocristaux peuvent s’en écarter.</p><p>Les principaux pics DRX des deux phases se recouvrent fortement. Une seule position de pic ne suffit pas à déterminer le rapport Fe²⁺/Fe³⁺. Les valeurs de maille citées correspondent à ces entrées précises.</p><p>Fe₃O₄ : masse molaire 231,533 g/mol, donnée du <a class=\"data-cite\" href=\"https://webbook.nist.gov/cgi/cbook.cgi?ID=C1317619&Units=SI\" target=\"_blank\" rel=\"noopener noreferrer\">NIST WebBook · CAS 1317-61-9</a>.</p></details></div>","<div class=\"text-module\"><h3>Two spinel-type oxides</h3><p>Oxygen surrounds two families of iron sites. A sites are tetrahedral: four oxygens surround the cation. B sites are octahedral: six oxygens surround it.</p><div class=\"phase-table\"><table><thead><tr><th>Ideal composition</th><th>Magnetite · Fe₃O₄</th><th>Maghemite · γ-Fe₂O₃</th></tr></thead><tbody><tr><th>A sites</th><td>Fe³⁺</td><td>Fe³⁺</td></tr><tr><th>B sites</th><td>Fe²⁺ + Fe³⁺</td><td>5/3 Fe³⁺ + 1/3 vacancy</td></tr><tr><th>Normalization</th><td>3 Fe per 4 O</td><td>8/3 Fe per 4 O</td></tr><tr><th>Ideal cation vacancies</th><td>None</td><td>1/6 of B sites</td></tr></tbody></table></div><p>Magnetite is an inverse spinel. At room temperature, B sites have mixed average valence. Fe²⁺/Fe³⁺ notation counts charges; it does not assign two distinct stationary positions. Oxidation towards maghemite removes Fe²⁺ and creates cation vacancies.</p><h3>From crystal structure to ferrimagnetism</h3><p>A and B sublattice moments oppose each other. They do not cancel. A net moment remains: this is ferrimagnetism. <a class=\"data-cite\" href=\"https://goldbook.iupac.org/terms/view/M03690\" target=\"_blank\" rel=\"noopener noreferrer\">IUPAC M03690</a></p><p>The collinear ionic model gives 4 μB per Fe₃O₄ for magnetite and 10/3 μB per Fe₈/₃O₄ for maghemite. These balances use high-spin Fe³⁺: 5 μB, and high-spin Fe²⁺: 4 μB. Measured magnetization also depends on temperature, defects and surfaces.</p><details><summary>View coordination from crystallographic coordinates</summary><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 390\" role=\"img\" aria-label=\"Iron coordination in magnetite\"><defs><radialGradient id=\"oxygenPhase\"><stop stop-color=\"#f8e2dd\"/><stop offset=\"1\" stop-color=\"#be6a5f\"/></radialGradient><radialGradient id=\"ironPhase\"><stop stop-color=\"#c6dceb\"/><stop offset=\"1\" stop-color=\"#31579c\"/></radialGradient></defs><path d=\"M201.7 281.9L145.7 138.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M201.7 281.9L304.3 180.5\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M201.7 281.9L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M145.7 138.6L304.3 180.5\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M145.7 138.6L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M304.3 180.5L248.3 139.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M225 185L201.7 281.9\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L145.7 138.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L304.3 180.5\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M225 185L248.3 139.1\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><circle cx=\"304.3\" cy=\"180.5\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"304.3\" y=\"185.5\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"145.7\" cy=\"138.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"145.7\" y=\"143.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"225.0\" cy=\"185.0\" r=\"22\" fill=\"url(#ironPhase)\"/><text x=\"225.0\" y=\"190.0\" text-anchor=\"middle\" fill=\"white\" font-size=\"14\">Fe</text><circle cx=\"201.7\" cy=\"281.9\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"201.7\" y=\"286.9\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"248.3\" cy=\"139.1\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"248.3\" y=\"144.1\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><text x=\"225\" y=\"48\" text-anchor=\"middle\" font-size=\"21\" fill=\"#243944\">A site · tetrahedral</text><text x=\"225\" y=\"330\" text-anchor=\"middle\" font-size=\"17\" fill=\"#243944\">Fe–O ≈ 1.889 Å · 4 O</text><path d=\"M579.3 233.4L725.9 272.1\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L674.1 139.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L675.9 230.4\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M579.3 233.4L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L674.1 139.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L675.9 230.4\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M725.9 272.1L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M674.1 139.6L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M674.1 139.6L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675.9 230.4L624.1 97.9\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675.9 230.4L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M624.1 97.9L770.7 136.6\" stroke=\"#b8a7a1\" stroke-width=\"2\" fill=\"none\"/><path d=\"M675 185L579.3 233.4\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L725.9 272.1\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L674.1 139.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L675.9 230.4\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L624.1 97.9\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><path d=\"M675 185L770.7 136.6\" stroke=\"#7c8fa1\" stroke-width=\"3\"/><circle cx=\"674.1\" cy=\"139.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"674.1\" y=\"144.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"725.9\" cy=\"272.1\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"725.9\" y=\"277.1\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"579.3\" cy=\"233.4\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"579.3\" y=\"238.4\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"675.0\" cy=\"185.0\" r=\"22\" fill=\"url(#ironPhase)\"/><text x=\"675.0\" y=\"190.0\" text-anchor=\"middle\" fill=\"white\" font-size=\"14\">Fe</text><circle cx=\"770.7\" cy=\"136.6\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"770.7\" y=\"141.6\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"624.1\" cy=\"97.9\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"624.1\" y=\"102.9\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><circle cx=\"675.9\" cy=\"230.4\" r=\"16\" fill=\"url(#oxygenPhase)\"/><text x=\"675.9\" y=\"235.4\" text-anchor=\"middle\" fill=\"#5c302b\" font-size=\"14\">O</text><text x=\"675\" y=\"48\" text-anchor=\"middle\" font-size=\"21\" fill=\"#243944\">B site · octahedral</text><text x=\"675\" y=\"330\" text-anchor=\"middle\" font-size=\"17\" fill=\"#243944\">Fe–O ≈ 2.058 Å · 6 O</text></svg><p>Oxygen neighbours and distances calculated from the magnetite CIF. Polyhedra are oriented for readability. <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9007644.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9007644 · Fleet, 1981</a></p></details><details><summary>Symmetry, unit-cell parameters and identification</summary><p>Magnetite: Fd3̅m, a = 8.3941 Å in entry <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9007644.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9007644 · Fleet, 1981</a>. The conventional cell contains 8 A sites, 16 B sites and 32 oxygens.</p><p>Maghemite: entry <a class=\"data-cite\" href=\"https://qiserver.ugr.es/cod/9017489.html\" target=\"_blank\" rel=\"noopener noreferrer\">COD 9017489 · Shmakov et al., 1995</a> describes a cubic P4₃32 structure with a = 8.3474 Å. Vacancy order can produce other symmetries, including a tetragonal superstructure. B-site vacancies define an ideal reference; nanocrystals can depart from it.</p><p>The main XRD peaks of both phases overlap strongly. A single peak position cannot determine the Fe²⁺/Fe³⁺ ratio. The quoted unit-cell values refer to these specific entries.</p><p>Fe₃O₄: molar mass 231.533 g/mol, from <a class=\"data-cite\" href=\"https://webbook.nist.gov/cgi/cbook.cgi?ID=C1317619&Units=SI\" target=\"_blank\" rel=\"noopener noreferrer\">NIST WebBook · CAS 1317-61-9</a>.</p></details></div>"],"steps":[],"refs":["fleet1981","greaves1983","shmakov1995","neelferrite1948"],"limits":["",""]},"monodomain":{"a":0,"kind":"domain","static":false,"n":["Particule monodomaine","Single-domain particle"],"lead":["Un moment magnétique décrit l’intensité et la direction de la réponse magnétique d’un objet. L’aimantation M est le moment total par unité de volume. Une particule monodomaine ne contient pas de paroi interne.","A magnetic moment describes the strength and direction of an object’s magnetic response. Magnetization M is the total moment per unit volume. A single-domain particle has no internal domain wall."],"steps":[["Domaines","Domains","Une paroi sépare deux domaines. Chaque domaine possède une direction d’aimantation.","A wall separates two domains. Each domain has a magnetization direction."],["Déplacement de paroi","Domain-wall displacement","Le déplacement de la paroi modifie les volumes des domaines.","Wall displacement changes the domain volumes."],["Monodomaine","Single domain","Une particule monodomaine ne contient pas de paroi interne.","A single-domain particle has no internal domain wall."]],"refs":["frenkel","kittel"],"limits":["",""],"notes":["M et H s’expriment en A/m. H désigne le champ magnétique appliqué. B désigne l’induction magnétique, en teslas. μ₀H est exprimé en teslas.","M and H are expressed in A/m. H denotes the applied magnetic field. B denotes magnetic flux density, in teslas. μ₀H is expressed in teslas."]},"macrospin":{"a":0,"n":["Rotation cohérente et spin géant","Coherent rotation and giant spin"],"kind":"spin","src":"hdr-macrospin","refs":["neelferrite1948","frenkel","sw"],"lead":["La magnétite et la maghémite sont ferrimagnétiques. Leurs sous-réseaux portent des moments opposés qui ne se compensent pas. Dans l’approximation de rotation cohérente, leur moment résultant tourne comme un seul vecteur.","Magnetite and maghemite are ferrimagnetic. Their sublattices carry opposing moments that do not cancel. In the coherent-rotation approximation, their net moment rotates as a single vector."],"steps":[["Rotation cohérente","Coherent rotation","Les moments de chaque sous-réseau tournent ensemble. Les deux sous-réseaux restent opposés dans cette représentation ferrimagnétique.","Moments in each sublattice rotate together. The two sublattices remain antiparallel in this ferrimagnetic representation."],["Moment résultant","Net moment","La somme vectorielle tourne avec les moments internes. Sa norme est supposée constante.","The vector sum rotates with the internal moments. Its magnitude is assumed constant."],["Spin géant","Giant spin","Une seule flèche représente désormais la nanoparticule. Cette approximation sera utilisée pour l’anisotropie et les relaxations.","One arrow now represents the nanoparticle. This approximation will be used for anisotropy and relaxation."]],"limits":["",""]},"anisotropy":{"a":0,"n":["Axes facile et difficile","Easy and hard axes"],"kind":"anisotropy","src":"02-anisotropie","refs":["sw"],"lead":["L’axe facile correspond aux minima du potentiel. Une direction perpendiculaire correspond à son maximum dans le modèle uniaxial à champ nul.","The easy axis corresponds to potential minima. A perpendicular direction corresponds to its maximum in the zero-field uniaxial model."],"steps":[["Minimum","Minimum","À champ nul, les deux directions de l’axe facile ont la même énergie.","At zero field, both directions along the easy axis have the same energy."],["Barrière","Barrier","La barrière vaut ΔE = KV. K est une densité d’énergie, en J/m³. V est le volume magnétique, en m³. La structure cristalline, la forme et la surface contribuent à l’anisotropie effective.","The barrier is ΔE = KV. K is an energy density in J/m³. V is the magnetic volume in m³. Crystal structure, shape and surface contribute to effective anisotropy."],["Autre minimum","Other minimum","Le moment atteint l’autre direction de l’axe facile. Son énergie retrouve un minimum.","The moment reaches the other easy-axis direction. Its energy returns to a minimum."]],"limits":["",""]},"swangle":{"a":0,"kind":"curves","mode":"swangle","n":["Stoner–Wohlfarth : angle","Stoner–Wohlfarth: angle"],"limits":["",""]},"relax":{"a":0,"n":["Relaxations de Néel et brownienne","Néel and Brownian relaxation"],"kind":"relax","src":"04-relaxations","refs":["neel","bean","brown","heat"],"lead":["Le moment peut se réorienter dans la particule ou avec elle.","The moment can reorient within the particle or with it."],"steps":[["Néel","Néel","Le moment se retourne dans la particule. Le corps reste fixe. L’agitation thermique permet de franchir la barrière d’anisotropie. Le temps caractéristique est τN.","The moment reverses within the particle. Its body stays fixed. Thermal fluctuations enable crossing of the anisotropy barrier. The characteristic time is τN."],["Rotation brownienne","Brownian rotation","La particule tourne dans le liquide. Le moment reste ici attaché à son axe facile. Le temps τB dépend de la viscosité et du volume hydrodynamique. Brown (1963) décrit les fluctuations internes ; Rosensweig (2002) présente les deux mécanismes de relaxation.","The particle rotates in the liquid. Its moment remains attached to its easy axis here. The time τB depends on viscosity and hydrodynamic volume. Brown (1963) describes internal fluctuations; Rosensweig (2002) presents both relaxation mechanisms."],["Immobilisation","Immobilization","Immobiliser la particule supprime la rotation brownienne, mais pas nécessairement les retournements de Néel.","Immobilizing the particle suppresses Brownian rotation, but not necessarily Néel reversals."]],"limits":["",""],"notes":["La forme exponentielle de τN concerne ici une barrière uniaxiale élevée, à champ nul. τ₀ est un paramètre du modèle. Le temps brownien utilise le volume hydrodynamique, et non celui du cœur seul.","The exponential form of τN describes a high uniaxial barrier at zero field here. τ₀ is a model parameter. Brownian time uses hydrodynamic volume, not core volume alone."]},"zfc":{"a":0,"n":["Superparamagnétisme et blocage — ZFC / FC","Superparamagnetism and blocking — ZFC / FC"],"kind":"curves","mode":"zfc","limits":["",""]},"mh":{"a":0,"n":["Lire un cycle M(H)","Reading an M(H) loop"],"kind":"curves","mode":"mh","limits":["",""]},"initial":{"a":0,"n":["Première aimantation : Langevin","Initial magnetization: Langevin"],"kind":"curves","mode":"initial","limits":["",""]},"interactions":{"a":1,"n":["Interactions entre particules","Interparticle interactions"],"kind":"dipole","src":"03-interactions","refs":["morup2010"],"lead":["Partez de particules isolées. Rapprochez-les pour renforcer le couplage dipolaire. Au contact magnétique direct, un échange ferromagnétique est représenté.","Start with isolated particles. Bring them closer to strengthen dipolar coupling. Ferromagnetic exchange is represented at direct magnetic contact."],"steps":[["Distance et corrélations","Distance and correlations","Les moments fluctuent en continu. Le voisin modifie leur énergie d’orientation. Au contact direct des cœurs, un échange ferromagnétique est imposé ici.","The moments fluctuate continuously. The neighbour changes their orientation energy. Ferromagnetic exchange is imposed here at direct core contact."]],"limits":["",""],"auto":true,"static":true,"notes":["La distance r relie les centres. Le couplage dipolaire dépend aussi de l’orientation des moments. Il peut favoriser ou contrarier leur alignement. L’échange exige un chemin de couplage adapté ; il n’apparaît pas à une distance universelle. Ici, J > 0 impose un échange ferromagnétique au contact direct.","Distance r joins the centres. Dipolar coupling also depends on moment orientation. It can favour or oppose alignment. Exchange requires a suitable coupling pathway; it has no universal onset distance. Here, J > 0 imposes ferromagnetic exchange at direct contact."],"reviews":["krishnan2010"]},"rem":{"a":1,"kind":"delta","static":true,"n":["Couplage magnétique · ΔM","Magnetic coupling · ΔM"],"lead":["ΔM compare deux courbes de rémanence à une référence sans interactions.","ΔM compares two remanence curves with a noninteracting reference."],"steps":[["Interpréter le signe","Interpreting the sign","Dans le cadre uniaxial de Wohlfarth, ΔM > 0 indique une tendance magnétisante ; ΔM < 0 indique une tendance démagnétisante. Le signe ne détermine pas à lui seul la nature de l’échange. Une anisotropie cubique peut produire un ΔM positif sans interactions.","Within the uniaxial Wohlfarth framework, ΔM > 0 indicates a magnetizing tendency; ΔM < 0 indicates a demagnetizing tendency. The sign alone does not identify the exchange mechanism. Cubic anisotropy can produce positive ΔM without interactions."]],"refs":["wohlfarth1958","henkel1964","kelly1989","harrell1993","garciaotero2000"],"limits":["",""],"notes":["IRM signifie aimantation rémanente isotherme ; DCD désigne la désaimantation par champ continu inverse. Les mesures sont réalisées à champ nul après chaque impulsion. mIRM et mDCD sont divisées par la même rémanence à saturation. La référence de Wohlfarth concerne des particules uniaxiales sans interactions et une activation thermique négligeable.","IRM means isothermal remanent magnetization; DCD means direct-current demagnetization. Measurements are made at zero field after each pulse. mIRM and mDCD are divided by the same saturation remanence. The Wohlfarth reference concerns noninteracting uniaxial particles with negligible thermal activation."]},"forc":{"a":1,"n":["FORC","FORC"],"kind":"curves","mode":"forc","limits":["",""]},"corona":{"a":2,"n":["Identité biologique","Biological identity"],"kind":"corona","src":"12-corona","refs":["vroman1969","cedervall2007","lundqvist2008","corona","ashby2014","tenzer2013"],"lead":["Une IONP acquiert une couronne biomoléculaire dans le plasma. Cette couronne évolue avant la rencontre cellulaire.","An IONP acquires a biomolecular corona in plasma. This corona evolves before cell encounter."],"steps":[["Injection","Injection","Les nanoparticules entrent dans le sang. Elles rencontrent les protéines du plasma.","Nanoparticles enter the bloodstream. They encounter plasma proteins."],["Adsorption des protéines","Protein adsorption","Les protéines diffusent vers la surface et s’y adsorbent. Une couronne se forme.","Proteins diffuse towards the surface and adsorb. A corona forms."],["Échanges · effet Vroman","Exchange · Vroman effect","Des protéines adsorbées peuvent être remplacées. Un remplacement favorisé par l’affinité correspond à l’effet Vroman. Les vitesses d’échange dépendent des protéines, de la surface et du milieu.","Adsorbed proteins can be replaced. Affinity-driven replacement corresponds to the Vroman effect. Exchange rates depend on proteins, surface and medium."],["Interaction cellulaire","Cell interaction","La cellule rencontre la couronne protéique. Cette identité biologique influence la reconnaissance et l’entrée cellulaire.","The cell encounters the protein corona. This biological identity influences recognition and cell entry."]],"limits":["",""],"reviews":["mahmoudi2011"],"notes":["L’affinité décrit l’équilibre de liaison. Les vitesses d’adsorption et de désorption règlent les échanges. Le revêtement, la taille et le milieu modifient la couronne. Le remplacement de type Vroman dépend du couple surface–protéines. Des échanges peuvent se produire sans changement majeur des espèces détectées. Tenzer et al. l’observent sur des particules de silice et de polystyrène. Ashby et al. étudient directement la dynamique de la couronne des IONPs.","Affinity describes binding equilibrium. Adsorption and desorption rates govern exchange. Coating, size and medium affect the corona. Vroman-type replacement depends on the surface–protein pair. Exchange can occur without major changes in the detected protein species. Tenzer et al. observe this on silica and polystyrene particles. Ashby et al. directly study IONP corona dynamics."]},"plasma":{"a":2,"kind":"reading","static":true,"n":["Cartographie du plasma","Plasma map"],"lead":["Abondance, adsorption et échanges sont trois propriétés distinctes.","Abundance, adsorption and exchange are distinct properties."],"body":["<div class=\"text-module\"><h3>Protéines abondantes : repères de concentration</h3><p>Plasma humain. Intervalles en g·L⁻¹, compilés par Schenk et al. (2008), tableau 3. Les masses des précurseurs ne servent pas à calculer des fractions moléculaires. α₂-macroglobuline : hommes adultes.</p><div class=\"plasma-map\"><div class=\"plasma-row\"><strong>Albumine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"35–52 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"260.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"175.00\" height=\"10\" fill=\"#26796a\"/></svg><span>35–52</span></div><div class=\"plasma-row\"><strong>Fibrinogène</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"2–4 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"20.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"10.00\" height=\"10\" fill=\"#26796a\"/></svg><span>2–4</span></div><div class=\"plasma-row\"><strong>α₂-macroglobuline</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.9–4 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"20.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"4.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.9–4</span></div><div class=\"plasma-row\"><strong>α₁-antitrypsine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.78–2 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"10.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"3.90\" height=\"10\" fill=\"#26796a\"/></svg><span>0.78–2</span></div><div class=\"plasma-row\"><strong>Haptoglobine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.3–2.2 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"11.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"1.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.3–2.2</span></div><div class=\"plasma-row\"><strong>Transthyrétine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.28–0.35 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"1.75\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"1.40\" height=\"10\" fill=\"#26796a\"/></svg><span>0.28–0.35</span></div><div class=\"plasma-row\"><strong>Céruloplasmine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.15–0.6 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"3.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"0.75\" height=\"10\" fill=\"#26796a\"/></svg><span>0.15–0.6</span></div><div class=\"plasma-row\"><strong>Prothrombine</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.1–0.1 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"0.50\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"0.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.1</span></div></div><p>Échelle linéaire commune : 0–52 g·L⁻¹. Vert foncé : borne basse ; vert clair : intervalle. Ces valeurs ne sont pas des pourcentages. La carte sélectionne des protéines ; elle ne représente pas la totalité du plasma.</p><h3>Immunoglobulines et autres familles</h3><p>Les immunoglobulines occupent aussi une place majeure. Le repère adulte pour les IgG sériques est de 7,67–15,90 g·L⁻¹. Il est présenté séparément des valeurs plasmatiques. Transferrine, apolipoprotéines et complément complètent cette carte fonctionnelle. <a href=\"https://www.mayocliniclabs.com/test-catalog/Overview/800053\" target=\"_blank\" rel=\"noopener noreferrer\">Mayo Clinic · IgG</a>.</p><h3>Du plasma à la couronne des IONPs</h3><details><summary>Albumine et immunoglobulines</summary><p>La concentration et la compétition modifient leur adsorption. Une abondance élevée dans le plasma ne garantit pas une couronne dominée par cette protéine.</p></details><details><summary>Apolipoprotéines et transferrine</summary><p>Ashby et al. comparent des SPIONs de tailles et revêtements différents dans du sérum humain, notamment déplété. ApoA-I et la transferrine présentent des comportements dépendants de la particule. La transferrine stablement liée favorise davantage l’entrée cellulaire dans leur essai.</p></details><details><summary>Complément</summary><p>Chen et al. montrent la fixation et l’échange dynamique du complément sur la couronne de nanostructures d’oxyde de fer revêtues de dextrane. La présence de C3 renseigne sur une interaction immunitaire ; elle ne mesure pas seule une inflammation systémique.</p></details><details><summary>Fibrinogène et reconnaissance d’une cible</summary><p>Jacqmarcq et al. montrent le rôle du fibrinogène dans la couronne d’assemblages oxyde de fer–polydopamine pour la reconnaissance de microthrombi. Ce résultat illustre une fonction de la couronne liée au revêtement.</p></details><h3>Affinité, enrichissement et temps de résidence</h3><p>L’affinité est définie pour un couple protéine–surface et des conditions données. Un Kd demande une mesure d’équilibre. Une analyse protéomique mesure une composition après un protocole de séparation. Elle ne donne pas automatiquement un classement d’affinité. Le temps de résidence décrit encore une autre propriété.</p></div>","<div class=\"text-module\"><h3>Abundant proteins: concentration ranges</h3><p>Human plasma. Ranges in g·L⁻¹ compiled by Schenk et al. (2008), Table 3. Precursor masses are not used to calculate molecular fractions. α₂-macroglobulin: adult men.</p><div class=\"plasma-map\"><div class=\"plasma-row\"><strong>Albumin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"35–52 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"260.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"175.00\" height=\"10\" fill=\"#26796a\"/></svg><span>35–52</span></div><div class=\"plasma-row\"><strong>Fibrinogen</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"2–4 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"20.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"10.00\" height=\"10\" fill=\"#26796a\"/></svg><span>2–4</span></div><div class=\"plasma-row\"><strong>α₂-macroglobulin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.9–4 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"20.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"4.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.9–4</span></div><div class=\"plasma-row\"><strong>α₁-antitrypsin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.78–2 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"10.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"3.90\" height=\"10\" fill=\"#26796a\"/></svg><span>0.78–2</span></div><div class=\"plasma-row\"><strong>Haptoglobin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.3–2.2 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"11.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"1.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.3–2.2</span></div><div class=\"plasma-row\"><strong>Transthyretin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.28–0.35 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"1.75\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"1.40\" height=\"10\" fill=\"#26796a\"/></svg><span>0.28–0.35</span></div><div class=\"plasma-row\"><strong>Ceruloplasmin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.15–0.6 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"3.00\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"0.75\" height=\"10\" fill=\"#26796a\"/></svg><span>0.15–0.6</span></div><div class=\"plasma-row\"><strong>Prothrombin</strong><svg viewBox=\"0 0 260 18\" role=\"img\" aria-label=\"0.1–0.1 g/L\"><rect x=\"0\" y=\"4\" width=\"260\" height=\"10\" rx=\"5\" fill=\"#e7eeec\"/><rect x=\"0\" y=\"4\" width=\"0.50\" height=\"10\" fill=\"#9ac8bc\"/><rect x=\"0\" y=\"4\" width=\"0.50\" height=\"10\" fill=\"#26796a\"/></svg><span>0.1</span></div></div><p>Common linear scale: 0–52 g·L⁻¹. Dark green: lower bound; light green: range. Values are not percentages. The map selects proteins; it does not represent all plasma components.</p><h3>Immunoglobulins and other families</h3><p>Immunoglobulins are also major components. The adult serum IgG reference range is 7.67–15.90 g·L⁻¹. It is shown separately from plasma values. Transferrin, apolipoproteins and complement complete this functional map. <a href=\"https://www.mayocliniclabs.com/test-catalog/Overview/800053\" target=\"_blank\" rel=\"noopener noreferrer\">Mayo Clinic · IgG</a>.</p><h3>From plasma to the IONP corona</h3><details><summary>Albumin and immunoglobulins</summary><p>Concentration and competition affect adsorption. High plasma abundance does not guarantee that a protein dominates the corona.</p></details><details><summary>Apolipoproteins and transferrin</summary><p>Ashby et al. compare SPION sizes and coatings in human serum, including depleted serum. ApoA-I and transferrin show particle-dependent behaviour. Stably bound transferrin promotes more uptake in their assay.</p></details><details><summary>Complement</summary><p>Chen et al. demonstrate complement binding and dynamic exchange on the corona of dextran-coated iron oxide nanostructures. C3 presence reports an immune interaction; alone, it does not measure systemic inflammation.</p></details><details><summary>Fibrinogen and target recognition</summary><p>Jacqmarcq et al. show the role of fibrinogen in the corona of iron oxide–polydopamine assemblies for microthrombus recognition. This result illustrates a coating-dependent corona function.</p></details><h3>Affinity, enrichment and residence time</h3><p>Affinity is defined for a protein–surface pair under specified conditions. A Kd requires an equilibrium measurement. Proteomics measures composition after a separation protocol. It does not automatically provide an affinity ranking. Residence time describes a different property.</p></div>"],"steps":[],"refs":["schenk2008","ashby2014","chen2017","jacqmarcq2024"],"limits":["",""]},"fate":{"a":2,"n":["Devenir intracellulaire","Intracellular fate"],"kind":"fate","src":"13-endolysosomes","refs":["fate","volatron2017","bugg2026","rink","membrane","chithrani2006","champion2006","portilla2022"],"lead":["Les nanoparticules entrent dans les cellules par endocytose. Elles peuvent rejoindre les compartiments lysosomaux.","Nanoparticles enter cells through endocytosis. They can reach lysosomal compartments."],"steps":[["Invagination","Invagination","La membrane plasmique se déforme autour de plusieurs nanoparticules.","The plasma membrane bends around several nanoparticles."],["Fermeture","Scission","La vésicule se ferme. Les particules restent dans sa lumière. Elle rejoint la voie endosomale.","The vesicle closes. Particles remain in its lumen. It enters the endosomal pathway."],["Maturation","Maturation","Le compartiment porteur des particules mûrit. L’endosome précoce évolue vers un endosome tardif.","The particle-bearing compartment matures. The early endosome develops into a late endosome."],["Fusion lysosomale","Lysosomal fusion","L’endosome tardif fusionne avec un lysosome. Les particules restent confinées dans le compartiment endolysosomal.","The late endosome fuses with a lysosome. Particles remain confined in the endolysosomal compartment."],["Marginalisation","Peripheral redistribution","Dans le système étudié par Lartigue et al. (2013), les nanocubes se dispersent. Ils se retrouvent principalement à la périphérie lysosomale.","In the system studied by Lartigue et al. (2013), nanocubes disperse. They mainly occur at the lysosomal periphery."],["Dégradation et stockage du fer","Degradation and iron storage","Les IONPs se dissolvent et libèrent du fer. Des cages initialement vides, les apoferritines, peuvent stocker ce fer dans un cœur minéral : elles deviennent des ferritines chargées. Volatron et al. (2017) montrent ce stockage en milieu mimant le lysosome. Le zoom illustre les étapes chimiques, sans imposer un trajet subcellulaire direct.","IONPs dissolve and release iron. Initially empty cages, apoferritins, can store this iron in a mineral core and become iron-loaded ferritins. Volatron et al. (2017) demonstrate this storage in a lysosome-like medium. The zoom illustrates chemical steps without prescribing a direct subcellular route."]],"limits":["",""],"notes":["La taille hydrodynamique, la forme, le revêtement et la couronne influencent l’adhésion et l’internalisation. Leur effet dépend du type cellulaire et du milieu. Chithrani étudie des nanoparticules d’or ; Champion étudie la phagocytose de particules modèles. Ces résultats ne fixent pas une taille optimale universelle pour les IONPs. Sur des IONPs de même taille de cœur, Portilla et al. montrent que l’effet du revêtement sur le trafic endolysosomal dépend du type cellulaire.","Hydrodynamic size, shape, coating and corona influence adhesion and internalization. Their effects depend on cell type and medium. Chithrani studies gold nanoparticles; Champion studies phagocytosis of model particles. These results do not define a universal optimum size for IONPs. For IONPs with the same core size, Portilla et al. show that the coating effect on endolysosomal trafficking depends on cell type."]},"response":{"a":2,"kind":"reading","static":true,"n":["Réponses cellulaires aux nanoparticules","Cellular responses to nanoparticles"],"lead":["La réponse dépend de la particule, de la dose, du temps et du système biologique.","Responses depend on the particle, dose, time and biological system."],"body":["<div class=\"text-module\"><h3>Taille, forme et charge de surface</h3><p>La cellule rencontre une particule avec son revêtement, sa couronne et ses agrégats éventuels. La taille du cœur et la taille hydrodynamique décrivent donc des objets différents.</p><ul><li><strong>Taille.</strong> Elle influence le contact membranaire, l’internalisation et le devenir intracellulaire. À masse égale, le nombre de particules et la surface exposée varient avec leur taille.</li><li><strong>Forme.</strong> La courbure locale et l’orientation au contact modifient l’enveloppement membranaire. Une sphère, un bâtonnet et un assemblage ne présentent pas la même interface.</li><li><strong>Charge.</strong> Elle influence les interactions avec les protéines et la membrane. Le potentiel zêta dépend du pH, des ions et du milieu. La couronne peut modifier la charge apparente et masquer des ligands.</li></ul><p>Ces paramètres agissent ensemble. Leur effet sur les ROS, l’inflammation ou la viabilité dépend aussi de la dose, du temps et du type cellulaire. Une charge positive ou une petite taille ne suffit pas à prédire la toxicité. Les comparaisons doivent préciser la dose en masse, en nombre ou en surface.</p><h3>Exemples sur les oxydes de fer</h3><p>Hirsch et al. comparent des SPIONs de charges différentes. La charge, la stabilité colloïdale et l’internalisation sont liées. Une internalisation accrue ne signifie pas une cytotoxicité accrue. Portilla et al. comparent deux revêtements sur un même cœur. Le trafic endolysosomal diffère chez les macrophages, mais pas dans les cellules tumorales étudiées.</p><h3>Couronne et reconnaissance cellulaire</h3><p>Francia et al. modifient la quantité de sérum lors de la formation de la couronne. Sur des particules de silice, la reconnaissance par les récepteurs et les voies d’entrée changent. Aliyandi et al. observent qu’une préadsorption de glycoprotéine riche en histidine réduit l’entrée de silice dans leurs modèles endothéliaux.</p><p>Sur des IONPs, Portilla et al. comparent plusieurs revêtements. Des couronnes de composition proche peuvent accompagner des réponses cellulaires différentes. La couronne ne supprime donc pas tous les effets du revêtement.</p><h3>Adaptation et homéostasie</h3><p>La cellule peut stocker le fer et renforcer ses défenses antioxydantes. NRF2 régule des gènes de protection. Une réponse adaptative ne signifie pas une immunité adaptative.</p><h3>ROS et stress oxydant</h3><p>Les espèces réactives de l’oxygène comprennent le superoxyde, le peroxyde d’hydrogène et le radical hydroxyle. Le peroxyde d’hydrogène n’est pas un radical. Le stress oxydant apparaît lorsque les processus oxydants dépassent les capacités de régulation et de réparation.</p><h3>Réaction de Fenton</h3><p>L’écriture classique décrit la réaction de Fe²⁺ avec H₂O₂. Les ligands, le pH et la disponibilité du fer modifient la réactivité. Du fer total mesuré ne donne pas directement la quantité de fer réactif.</p><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><msup><mi mathvariant=\"normal\">Fe</mi><mrow><mn>2</mn><mo>+</mo></mrow></msup><mo>+</mo><msub><mi mathvariant=\"normal\">H</mi><mn>2</mn></msub><msub><mi mathvariant=\"normal\">O</mi><mn>2</mn></msub><mo>→</mo><msup><mi mathvariant=\"normal\">Fe</mi><mrow><mn>3</mn><mo>+</mo></mrow></msup><mo>+</mo><msup><mi mathvariant=\"normal\">OH</mi><mo>−</mo></msup><mo>+</mo><mi mathvariant=\"normal\">HO</mi><mo>•</mo></math><h3>Peroxydation lipidique et ferroptose</h3><p>La ferroptose est une mort cellulaire régulée dépendante du fer. Elle implique une accumulation de peroxydes lipidiques. GPX4 réduit ces peroxydes en utilisant le glutathion. Une augmentation des ROS, seule, ne démontre pas une ferroptose. Il faut relier la mort aux lipides oxydés et tester des interventions protectrices adaptées.</p><h3>Réponse inflammatoire cellulaire</h3><p>Les macrophages peuvent modifier leur production de cytokines après exposition. Zanganeh et al. observent une réponse pro-inflammatoire et un effet antitumoral avec le ferumoxytol dans des modèles murins. Ce résultat concerne une formulation et des conditions précises.</p><h3>De la cellule à l’organisme</h3><p>La réponse systémique dépend de la dose, de la voie d’administration, de la distribution et de la clairance. Complément, cytokines circulantes et tissus apportent des informations distinctes. Une mesure en culture ne suffit pas à décrire l’ensemble de l’organisme.</p><p><a href=\"#biointerfaces/fate\">Revenir au devenir intracellulaire</a></p></div>","<div class=\"text-module\"><h3>Size, shape and surface charge</h3><p>Cells encounter a particle together with its coating, corona and possible aggregates. Core size and hydrodynamic size therefore describe different objects.</p><ul><li><strong>Size.</strong> It influences membrane contact, uptake and intracellular fate. At equal mass, particle number and exposed surface area vary with size.</li><li><strong>Shape.</strong> Local curvature and contact orientation affect membrane wrapping. A sphere, a rod and an assembly present different interfaces.</li><li><strong>Charge.</strong> It influences interactions with proteins and membranes. Zeta potential depends on pH, ions and medium. The corona can modify apparent charge and mask ligands.</li></ul><p>These parameters act together. Their effects on ROS, inflammation or viability also depend on dose, time and cell type. Positive charge or small size alone does not predict toxicity. Comparisons should specify whether dose is expressed as mass, number or surface area.</p><h3>Iron oxide examples</h3><p>Hirsch et al. compare SPIONs with different charges. Charge, colloidal stability and uptake are linked. Increased uptake does not imply increased cytotoxicity. Portilla et al. compare two coatings on the same core. Endolysosomal trafficking differs in macrophages, but not in the studied tumour cells.</p><h3>Corona and cellular recognition</h3><p>Francia et al. vary the amount of serum during corona formation. On silica particles, receptor recognition and uptake pathways change. Aliyandi et al. find that preadsorbed histidine-rich glycoprotein reduces silica uptake in their endothelial models.</p><p>On IONPs, Portilla et al. compare several coatings. Coronas with similar compositions can accompany different cellular responses. The corona therefore does not erase every coating effect.</p><h3>Adaptation and homeostasis</h3><p>Cells can store iron and strengthen antioxidant defences. NRF2 regulates protective genes. An adaptive cellular response is distinct from adaptive immunity.</p><h3>ROS and oxidative stress</h3><p>Reactive oxygen species include superoxide, hydrogen peroxide and the hydroxyl radical. Hydrogen peroxide is not a radical. Oxidative stress arises when oxidizing processes exceed regulatory and repair capacity.</p><h3>Fenton reaction</h3><p>The classical equation describes Fe²⁺ reacting with H₂O₂. Ligands, pH and iron availability affect reactivity. Total measured iron does not directly give the amount of reactive iron.</p><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><msup><mi mathvariant=\"normal\">Fe</mi><mrow><mn>2</mn><mo>+</mo></mrow></msup><mo>+</mo><msub><mi mathvariant=\"normal\">H</mi><mn>2</mn></msub><msub><mi mathvariant=\"normal\">O</mi><mn>2</mn></msub><mo>→</mo><msup><mi mathvariant=\"normal\">Fe</mi><mrow><mn>3</mn><mo>+</mo></mrow></msup><mo>+</mo><msup><mi mathvariant=\"normal\">OH</mi><mo>−</mo></msup><mo>+</mo><mi mathvariant=\"normal\">HO</mi><mo>•</mo></math><h3>Lipid peroxidation and ferroptosis</h3><p>Ferroptosis is an iron-dependent regulated cell death. It involves lipid peroxide accumulation. GPX4 reduces these peroxides using glutathione. Increased ROS alone does not demonstrate ferroptosis. Cell death must be linked to oxidized lipids and tested with appropriate protective interventions.</p><h3>Cellular inflammatory response</h3><p>Macrophages can alter cytokine production after exposure. Zanganeh et al. observe a pro-inflammatory response and an antitumour effect with ferumoxytol in mouse models. This result concerns a specific formulation and defined conditions.</p><h3>From cells to the organism</h3><p>Systemic responses depend on dose, administration route, distribution and clearance. Complement, circulating cytokines and tissues provide distinct information. A culture measurement alone does not describe the whole organism.</p><p><a href=\"#biointerfaces/fate\">Return to intracellular fate</a></p></div>"],"steps":[],"refs":["chithrani2006","champion2006","salvati","ashby2014","itoh1997","fenton1894","dixon2012","yang2014","zanganeh2016","chen2017","hirsch2013","portilla2022","portilla2021","francia2019","aliyandi2021"],"limits":["",""]},"mri":{"a":2,"n":["IRM : T₁ et T₂","MRI: T₁ and T₂"],"kind":"mri","src":"review-fig2","refs":["bloch1946"],"lead":["Une impulsion RF de 90° bascule l’aimantation des protons. Les deux composantes relaxent ensuite simultanément.","A 90° RF pulse tips proton magnetization. Both components then relax simultaneously."],"steps":[["Impulsion RF","RF pulse","Le vecteur quitte l’axe longitudinal et atteint le plan transverse.","The vector leaves the longitudinal axis and reaches the transverse plane."],["Relaxation simultanée","Simultaneous relaxation","Mz récupère avec T₁. Mxy décroît avec T₂.","Mz recovers with T₁. Mxy decays with T₂."],["Retour à l’équilibre","Return to equilibrium","La composante transverse s’efface tandis que la composante longitudinale se reconstitue.","The transverse component disappears while the longitudinal component recovers."],["Équilibre","Equilibrium","L’aimantation retrouve progressivement sa valeur longitudinale M₀.","Magnetization progressively returns to its longitudinal value M₀."]],"limits":["",""],"notes":["T₁ caractérise le retour de Mz vers l’équilibre par échange d’énergie avec le milieu. T₂ caractérise la perte de cohérence transverse. T₂* inclut aussi le déphasage dû aux inhomogénéités de champ. Ici, la décroissance représentée est celle de T₂. Le vecteur représente l’aimantation des protons, pas le moment d’une IONP.","T₁ characterizes recovery of Mz through energy exchange with the surroundings. T₂ characterizes loss of transverse coherence. T₂* also includes dephasing due to field inhomogeneity. The decay shown here represents T₂. The vector represents proton magnetization, not an IONP moment."]},"relaxivity":{"a":2,"kind":"reading","static":true,"n":["Eau, IONPs et relaxivité","Water, IONPs and relaxivity"],"lead":["Les IONPs modifient la relaxation des protons de l’eau.","IONPs modify water-proton relaxation."],"body":["<div class=\"text-module\"><h3>Origine du contraste</h3><p>Les moments des IONPs créent des champs locaux. Le mouvement de l’eau et la dynamique magnétique modulent les champs ressentis par les protons. Ces mécanismes modifient T₁ et T₂.</p><h3>Mesurer les relaxivités</h3><p>La pente de 1/T₁ ou de 1/T₂ en fonction de la concentration en fer définit r₁ ou r₂. Il faut préciser le champ B₀, la température et le milieu.</p><h3>Structure et propriétés</h3><p>La taille du cœur, l’aimantation, le revêtement et l’agrégation influencent la relaxation. Un rapport r₂/r₁ élevé ne suffit pas, seul, à prédire la qualité d’une image.</p><h3>Comprendre la loi d’échelle de Vuong et al.</h3><p>La diffusion de l’eau moyenne les champs locaux lorsque Δωτ<sub>D</sub> est petit. Dans ce régime, r₂ augmente avec le carré de l’aimantation volumique et le carré de la taille, à composition fixée. Pour un assemblage, sa fraction volumique magnétique intervient aussi. Lorsque Δωτ<sub>D</sub> augmente, le régime change : cette croissance ne se prolonge pas indéfiniment.</p><details><summary>Diffusion et déphasage</summary><p>τ<sub>D</sub> est le temps de diffusion sur la taille de l’objet. Δω mesure le décalage de fréquence créé par son aimantation. Le régime de déphasage statique décrit surtout R₂*. La mesure de R₂ dépend aussi du refocalisage et de l’espacement des échos. Le diamètre pertinent est celui de l’objet imperméable à l’eau ; pour un assemblage, ce n’est pas automatiquement celui d’un cœur.</p></details><p>À aimantation saturée, dans le régime de moyennage par le mouvement, r₂φ<sub>intra</sub>/Mᵥ² varie comme d²/D. Mᵥ est l’aimantation par volume de l’objet entier. φ<sub>intra</sub> est sa fraction volumique magnétique. D est le coefficient de diffusion de l’eau. Pour un assemblage compact, Mᵥ = φ<sub>intra</sub>M<sub>cœur</sub>. À composition fixée, r₂ varie donc comme φ<sub>intra</sub>M<sub>cœur</sub>²d²/D.</p><details class=\"symbols\"><summary>Symboles et unités</summary><p>γ est le rapport gyromagnétique du proton, en rad·s⁻¹·T⁻¹. Rᵢ = 1/Tᵢ ; i = 1 ou 2. cFe est en mmol/L ; rᵢ en L·mmol⁻¹·s⁻¹. La relation linéaire s’applique dans le domaine de concentration validé expérimentalement.</p></details></div>","<div class=\"text-module\"><h3>Contrast mechanism</h3><p>IONP moments create local fields. Water motion and magnetic dynamics modulate the fields experienced by protons. These mechanisms modify T₁ and T₂.</p><h3>Measuring relaxivity</h3><p>The slope of 1/T₁ or 1/T₂ versus iron concentration defines r₁ or r₂. Report B₀, temperature and medium.</p><h3>Structure and properties</h3><p>Core size, magnetization, coating and aggregation influence relaxation. A high r₂/r₁ ratio alone does not predict image quality.</p><h3>Understanding the scaling law of Vuong et al.</h3><p>Water diffusion averages local fields when Δωτ<sub>D</sub> is small. In this regime, r₂ increases with squared volume magnetization and squared size at fixed composition. An assembly’s magnetic volume fraction also matters. As Δωτ<sub>D</sub> increases, the regime changes: this growth does not continue indefinitely.</p><details><summary>Diffusion and dephasing</summary><p>τ<sub>D</sub> is the diffusion time over the object size. Δω measures the frequency shift produced by its magnetization. Static dephasing mainly describes R₂*. Measured R₂ also depends on refocusing and echo spacing. The relevant diameter is that of the water-impermeable object; for an assembly, it is not automatically the core diameter.</p></details><p>At magnetic saturation, in the motional averaging regime, r₂φ<sub>intra</sub>/Mᵥ² scales as d²/D. Mᵥ is magnetization per volume of the whole object. φ<sub>intra</sub> is its magnetic volume fraction. D is the water diffusion coefficient. For a compact assembly, Mᵥ = φ<sub>intra</sub>M<sub>core</sub>. At fixed composition, r₂ therefore scales as φ<sub>intra</sub>M<sub>core</sub>²d²/D.</p><details class=\"symbols\"><summary>Symbols and units</summary><p>γ is the proton gyromagnetic ratio, in rad·s⁻¹·T⁻¹. Rᵢ = 1/Tᵢ; i = 1 or 2. cFe is in mmol/L; rᵢ in L·mmol⁻¹·s⁻¹. The linear relation applies over an experimentally validated concentration range.</p></details></div>"],"steps":[],"refs":["dias1986","roch1999","vuong2012"],"limits":["",""]},"mpi":{"a":2,"kind":"reading","static":true,"n":["Imagerie par particules magnétiques","Magnetic particle imaging"],"lead":["Le MPI détecte directement la réponse magnétique des traceurs.","MPI directly detects the magnetic response of tracers."],"body":["<div class=\"text-module\"><h3>Localiser le signal</h3><p>Un gradient crée une région de champ nul. Un champ d’excitation déplace cette région. Les particules proches répondent fortement ; les particules éloignées sont proches de la saturation.</p><h3>Réponse non linéaire</h3><p>La variation de l’aimantation induit une tension dans une bobine de réception. La réponse non linéaire contient des harmoniques. La reconstruction utilise la sensibilité spatiale et la réponse du traceur.</p><h3>Rôle du traceur</h3><p>Le moment magnétique, l’anisotropie et les temps de relaxation modifient le signal et la résolution. Le signal de particules présente peu de fond endogène ; le bruit instrumental subsiste.</p><p>La fonction de Langevin introduite dans l’axe 1 décrit une réponse d’équilibre idéale. En MPI, le champ varie rapidement : la relaxation peut retarder cette réponse. Le signal provient des particules, contrairement à l’IRM qui détecte les noyaux.</p><details class=\"symbols\"><summary>Symboles et unités</summary><p>u : tension reçue ; Φ : flux magnétique ; N : nombre de spires. La proportionnalité à dM/dt suppose une géométrie de détection fixée. Elle ne décrit pas à elle seule la reconstruction spatiale.</p></details></div>","<div class=\"text-module\"><h3>Localizing the signal</h3><p>A gradient creates a field-free region. A drive field moves this region. Nearby particles respond strongly; distant particles approach saturation.</p><h3>Nonlinear response</h3><p>Changing magnetization induces voltage in a receive coil. The nonlinear response contains harmonics. Reconstruction uses spatial sensitivity and tracer response.</p><h3>Tracer properties</h3><p>Magnetic moment, anisotropy and relaxation times affect signal and resolution. Particle signals have little endogenous background; instrumental noise remains.</p><p>The Langevin function introduced in axis 1 describes an ideal equilibrium response. In MPI, the field varies rapidly: relaxation can delay that response. The signal comes from particles, unlike MRI, which detects nuclei.</p><details class=\"symbols\"><summary>Symbols and units</summary><p>u: received voltage; Φ: magnetic flux; N: coil turns. Proportionality to dM/dt assumes fixed detection geometry. It does not by itself describe spatial reconstruction.</p></details></div>"],"steps":[],"refs":["mpi"],"limits":["",""],"reviews":["krishnan2010"]},"heat":{"a":2,"kind":"reading","static":true,"n":["Hyperthermie magnétique","Magnetic hyperthermia"],"lead":["Un champ alternatif transfère de l’énergie aux moments magnétiques. Une partie est dissipée en chaleur.","An alternating field transfers energy to magnetic moments. Some is dissipated as heat."],"body":["<div class=\"text-module\"><h3>Dissipation</h3><p>L’aire du cycle dynamique M(H) mesure l’énergie dissipée par cycle et par volume magnétique. La fréquence convertit cette énergie en puissance.</p><h3>Réponse linéaire de Rosensweig</h3><p>À faible excitation, χ″ décrit la composante dissipative. Un modèle à temps de relaxation unique relie χ″ à χ₀ et à 2πfτ. Cette approximation ne couvre pas tous les cycles non linéaires ni les assemblages fortement couplés.</p><h3>Anisotropie et relaxation</h3><p>La barrière K<sub>eff</sub>V contrôle le retournement de Néel. La rotation brownienne dépend de la viscosité et du volume hydrodynamique. Fortin et al. séparent ces contributions en variant la taille, l’anisotropie et la viscosité.</p><h3>Ajuster l’anisotropie</h3><p>Une anisotropie plus forte n’augmente pas toujours le chauffage. La réponse doit correspondre à l’amplitude et à la fréquence du champ. Lee et al., dans l’équipe de Cheon, utilisent le couplage d’échange cœur–coquille pour ajuster les propriétés magnétiques et augmenter la puissance dissipée.</p><h3>Comparer les mesures</h3><p>Le SAR rapporte la puissance à une masse explicitement définie : fer ou oxyde. En calorimétrie, il dépend de la capacité thermique totale et de la pente initiale de température. L’ILP n’est comparable que dans les conditions où la réponse linéaire est appropriée.</p><h3>Amplitude et fréquence : critère de Brezovich</h3><p>Le repère historique H₀f ≲ 4,85 × 10⁸ A·m⁻¹·s⁻¹ provient de conditions d’exposition particulières. Des critères moins restrictifs, autour de 5 × 10⁹, ont été proposés pour d’autres géométries. Aucun de ces produits ne garantit à lui seul la tolérance : volume exposé, durée et refroidissement comptent aussi.</p><p>Carrey et al. relient les cycles dynamiques aux conditions d’excitation. Leur approche permet de dépasser la réponse linéaire. Dans l’approximation de deux voies indépendantes, les vitesses de relaxation de Néel et brownienne s’additionnent.</p><p>Ici, M et χ sont rapportés au volume de phase magnétique. Pᵥ utilise le même volume. Si χ est mesurée par volume de suspension, la puissance volumique doit être divisée par la concentration massique de matériau magnétique, et non par sa masse volumique. Le SAR par masse de fer requiert une conversion supplémentaire.</p><p>Les retournements internes et la rotation mécanique contribuent à la même aire de cycle dynamique. Ajouter des « pertes de relaxation » à cette aire compterait deux fois leur contribution.</p><details class=\"symbols\"><summary>Symboles et unités</summary><p>H₀ est l’amplitude crête en A/m, f la fréquence en Hz, τ le temps de relaxation. M est une aimantation volumique. Pᵥ est en W/m³ de phase magnétique ; ρmag en kg/m³ donne un SAR en W/kg de phase magnétique. Ctot est la capacité thermique totale (J/K) et mmag la masse de référence (kg). Les pertes thermiques doivent être prises en compte.</p></details></div>","<div class=\"text-module\"><h3>Dissipation</h3><p>The area of the dynamic M(H) loop gives energy loss per cycle and magnetic volume. Frequency converts this energy into power.</p><h3>Rosensweig linear response</h3><p>At low excitation, χ″ describes the dissipative component. A single-relaxation-time model relates χ″ to χ₀ and 2πfτ. This approximation does not cover all nonlinear loops or strongly coupled assemblies.</p><h3>Anisotropy and relaxation</h3><p>The K<sub>eff</sub>V barrier controls Néel reversal. Brownian rotation depends on viscosity and hydrodynamic volume. Fortin et al. separate these contributions by varying size, anisotropy and viscosity.</p><h3>Tuning anisotropy</h3><p>Higher anisotropy does not always increase heating. The response must match the field amplitude and frequency. Lee et al., in Cheon’s group, use core–shell exchange coupling to tune magnetic properties and increase dissipated power.</p><h3>Comparing measurements</h3><p>SAR divides power by an explicitly defined mass: iron or oxide. Calorimetry uses total heat capacity and the initial temperature slope. ILP is comparable only when linear-response conditions are appropriate.</p><h3>Amplitude and frequency: the Brezovich criterion</h3><p>The historical guide H₀f ≲ 4.85 × 10⁸ A·m⁻¹·s⁻¹ comes from specific exposure conditions. Less restrictive criteria near 5 × 10⁹ have been proposed for other geometries. Neither product alone guarantees tolerance: exposed volume, duration and cooling also matter.</p><p>Carrey et al. relate dynamic loops to excitation conditions. Their approach extends beyond linear response. In the approximation of two independent pathways, Néel and Brownian relaxation rates add.</p><p>Here, M and χ refer to magnetic-phase volume. Pᵥ uses the same volume. If χ is measured per suspension volume, volumetric power must be divided by magnetic-material mass concentration, not its density. SAR per iron mass requires an additional conversion.</p><p>Internal reversals and mechanical rotation contribute to the same dynamic loop area. Adding “relaxation losses” to that area would count their contribution twice.</p><details class=\"symbols\"><summary>Symbols and units</summary><p>H₀ is peak amplitude in A/m, f is frequency in Hz, τ is relaxation time. M is volume magnetization. Pᵥ is in W/m³ of magnetic phase; ρmag in kg/m³ gives SAR in W/kg of magnetic phase. Ctot is total heat capacity (J/K) and mmag is reference mass (kg). Heat losses must be accounted for.</p></details></div>"],"steps":[],"refs":["gilchrist1957","neel","brown","heat","carrey2011","fortin2007","cheon2011","hergt2008","atkinson1984","kallumadil2009"],"limits":["",""],"reviews":["dutz2013","sandre2015","krishnan2010"]},"photo":{"a":2,"kind":"reading","static":true,"n":["Conversion photothermique","Photothermal conversion"],"lead":["La lumière absorbée peut être dissipée sous forme de chaleur.","Absorbed light can be dissipated as heat."],"body":["<div class=\"text-module\"><h3>Absorption et dissipation</h3><p>Les voies de relaxation non radiatives transfèrent l’énergie absorbée au milieu. La photothermie se distingue de la photodynamique, qui repose sur des espèces réactives.</p><h3>IONPs et assemblages</h3><p>L’absorption dépend de la composition, de la longueur d’onde et de l’organisation des particules. Des études sur les IONPs et leurs amas montrent une conversion dans le proche infrarouge. Le mécanisme plasmonique des nanoparticules d’or ne doit pas être transposé automatiquement aux IONPs.</p><h3>Bilan thermique</h3><p>La température résulte de la puissance absorbée et des pertes. Un blanc permet d’estimer le chauffage du solvant et du contenant. Le rendement dépend du bilan thermique et de la mesure de l’absorption.</p><details class=\"symbols\"><summary>Symboles et unités</summary><p>Ctot : capacité thermique totale ; η : rendement ; Pabs : puissance optique absorbée par les particules ; Pblanc : chauffage de fond ; G : conductance thermique effective ; Tenv : température du milieu. Modèle global à température uniforme, sans prédiction de température cellulaire locale.</p></details></div>","<div class=\"text-module\"><h3>Absorption and dissipation</h3><p>Nonradiative relaxation pathways transfer absorbed energy to the surroundings. Photothermal conversion differs from photodynamic action, which involves reactive species.</p><h3>IONPs and assemblies</h3><p>Absorption depends on composition, wavelength and particle organization. Studies of IONPs and clusters show near-infrared conversion. Gold-nanoparticle plasmonic mechanisms should not automatically be assigned to IONPs.</p><h3>Heat balance</h3><p>Temperature reflects absorbed power and heat losses. A blank estimates solvent and container heating. Efficiency depends on the heat balance and absorption measurement.</p><details class=\"symbols\"><summary>Symbols and units</summary><p>Ctot: total heat capacity; η: efficiency; Pabs: optical power absorbed by particles; Pblank: background heating; G: effective thermal conductance; Tenv: ambient temperature. Lumped uniform-temperature model, not a prediction of local cellular temperature.</p></details></div>"],"steps":[],"refs":["shen2013","shen2015","roper2007"],"limits":["",""]}};
function range(id,fr,en,min,max,val,step,unit){if(values[id]===undefined)values[id]=val;return `<label>${T(fr,en)}<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${values[id]}"><output>${values[id]} ${unit}</output></label>`;}
function controls(m){let s='';if(m.kind==='relax')s=`<label><input type="checkbox" id="fixed" ${values.fixed?'checked':''}> ${T('Particule immobilisée','Immobilized particle')}</label>`;if(m.kind==='dipole')s=range('gap','Distance entre surfaces','Surface gap',0,60,60,.1,'nm');if(m.kind==='delta')s=`<label>${T('Écart à la référence','Deviation from the reference')}<select id="deltaSign"><option value="0">${T('Sans écart : ΔM = 0','No deviation: ΔM = 0')}</option><option value="1">${T('Type ferromagnétique : ΔM > 0','Ferromagnetic-like: ΔM > 0')}</option><option value="-1">${T('Type antiferromagnétique : ΔM < 0','Antiferromagnetic-like: ΔM < 0')}</option></select></label>`;if(m.kind==='mri')s=range('T1','T₁','T₁',400,2000,1000,100,'ms')+range('T2','T₂','T₂',40,400,180,10,'ms');$('controls').innerHTML=s;if(m.kind==='dipole'&&values.gap>=60){const out=$('controls').querySelector('output');if(out)out.textContent=T('Isolées','Isolated');}if($('deltaSign')){$('deltaSign').value=String(values.deltaSign||0);$('deltaSign').onchange=()=>{values.deltaSign=+$('deltaSign').value;draw();};}if($('coronaMode')){$('coronaMode').value=values.coronaMode||'dynamic';$('coronaMode').onchange=()=>{values.coronaMode=$('coronaMode').value;draw();};}$('controls').querySelectorAll('input').forEach(el=>el.oninput=()=>{values[el.id]=el.type==='checkbox'?el.checked:+el.value;if(el.type==='range')el.nextElementSibling.textContent=el.value+' '+({spT:'K',sptm:'',gap:'nm',K:'kJ/m³',d:'nm',T:'K',shell:'nm',eta:'mPa·s',angle:'°',T1:'ms',T2:'ms'}[el.id]||'');if(el.id==='gap'&&+el.value>=60)el.nextElementSibling.textContent=T('Isolées','Isolated');draw();});}
function stop(){playing=false;cancelAnimationFrame(raf);if($('play'))$('play').textContent=current==='corona'&&u>0&&u<1?T('Poursuivre','Continue'):T('Lire','Play');}
function dataLink(url,label){return '<a class="data-cite" href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>';}
function renderDataNotes(){let html='';
 const kb='kB = 1.380649 × 10<sup>−23</sup> J/K · '+dataLink('https://physics.nist.gov/cuu/pdf/all.pdf','NIST CODATA 2022');
 if(['anisotropy','relax','zfc','interactions','heat'].includes(current))html='<p>'+kb+'</p>';
 if(['monodomain','macrospin','zfc'].includes(current))html+='<p>'+T('Définition de l’ordre magnétique : ','Magnetic-order definition: ')+dataLink('https://goldbook.iupac.org/terms/view/M03690','IUPAC Gold Book · M03690')+'</p>';
 if(current==='corona'){
  const proteins=[['Albumine / Albumin','1AO6'],['IgG','1HZH'],['Fibrinogène / Fibrinogen','3GHG']];
  html='<p>'+T('Silhouettes moléculaires issues des coordonnées Cα : ','Molecular silhouettes derived from Cα coordinates: ')+proteins.map(([name,id])=>dataLink('https://www.rcsb.org/structure/'+id,name+' · PDB '+id)).join(' · ')+'.</p><p>'+T('Hématie humaine : diamètre moyen 7,7 µm (8 mesures). ','Human red blood cell: mean diameter 7.7 µm (8 measurements). ')+dataLink('https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108239','BioNumbers · BNID 108239')+'. '+T('La scène agrandit les objets nanométriques ; leur nombre ne représente pas une concentration.','Nanoscale objects are enlarged in the scene; their number does not represent a concentration.')+'</p>';
 }
 if(current==='fate')html='<p>'+T('Repère pour la bicouche lipidique : environ 3–4 nm dans l’entrée citée. ','Lipid-bilayer dimensional reference: approximately 3–4 nm in the cited entry. ')+dataLink('https://bionumbers.hms.harvard.edu/bionumber.aspx?id=112585','BioNumbers · BNID 112585')+'</p>';
 $('dataNotes').innerHTML=html;
}

function render(){stop();renderDataNotes();renderResources();renderModuleNavigation();const m=D[current];document.documentElement.lang=lang;$('language').textContent=lang==='fr'?'EN':'FR';$('language').ariaLabel=T('Switch to English','Passer en français');$('edition').textContent=T('Bases théoriques','Theoretical background');$('eyebrow').textContent=T('Recherche · Explorer les mécanismes','Research · Explore the mechanisms');$('title').textContent=T('De la nanoparticule au vivant','From nanoparticles to living systems');$('intro').textContent=T('Les schémas et les modèles expliquent les mécanismes étudiés dans nos trois axes de recherche.','Diagrams and models explain the mechanisms studied across our three research axes.');$('axes').innerHTML=axes.map((a,i)=>`<button data-axis="${i}" aria-pressed="${i===axis}"><span class="axis-number">0${i+1}</span><b>${a[lang==='fr'?0:1]}</b><span>${a[lang==='fr'?2:3]}</span><span class="axis-open">${i===axis?T('Axe sélectionné','Selected axis'):T('Explorer cet axe','Explore this axis')}</span></button>`).join('');$('axes').querySelectorAll('button').forEach(b=>b.onclick=()=>{chooseModule(Object.keys(D).find(k=>D[k].a===+b.dataset.axis));});$('modules').innerHTML=Object.entries(D).filter(([k,v])=>v.a===axis).map(([k,v])=>`<button data-module="${k}" aria-pressed="${current===k}">${v.n[lang==='fr'?0:1]}</button>`).join('');$('modules').querySelectorAll('button').forEach(b=>b.onclick=()=>{chooseModule(b.dataset.module);});$('heading').innerHTML=`<p class="eyebrow">${axes[axis][lang==='fr'?0:1]}</p><h2>${m.n[lang==='fr'?0:1]}</h2><p>${m.lead?m.lead[lang==='fr'?0:1]:''}</p>`;$('stage').innerHTML='';controls(m);const iscurve=m.kind==='curves';$('enlarge').hidden=iscurve;$('enlarge').textContent=T('Agrandir le schéma','Enlarge diagram');$('zoomTitle').textContent=T('Vue agrandie · animation en pause','Enlarged view · animation paused');$('closeZoom').textContent=T('Fermer','Close');['transport','steps','explain','math','references','limits'].forEach(id=>$(id).hidden=iscurve);if(iscurve){if(current==='forc'){$('references').hidden=false;$('references').innerHTML='<h3>'+T('Publications de référence','Reference publications')+'</h3>'+['pike1999','roberts2000'].map(k=>'<p>'+refs[k][0]+'. <a href="https://doi.org/'+refs[k][1]+'" target="_blank" rel="noopener noreferrer">doi: '+refs[k][1]+'</a></p>').join('');}$('stage').innerHTML='<iframe id="curves" title="'+T('Modèles de magnétisme interactifs','Interactive magnetism models')+'"></iframe>';const f=$('curves');f.onload=()=>f.contentWindow.postMessage({kind:'protocol',mode:m.mode,lang},'*');f.srcdoc=['swangle','zfc','mh','initial'].includes(m.mode)?ASSETS.foundations:ASSETS.curves;return;}$('reset').textContent=T('Recommencer','Restart');$('timelineLabel').textContent=T('Progression','Progress');$('steps').innerHTML=m.steps.map((s,i)=>`<button data-step="${i}">${i+1}. ${s[lang==='fr'?0:1]}</button>`).join('');$('steps').querySelectorAll('button').forEach(b=>b.onclick=()=>{stop();u=current==='corona'?[.25,.5,.75,1][+b.dataset.step]:current==='fate'&&+b.dataset.step===5?5/6:(+b.dataset.step+.5)/m.steps.length;draw();});$('references').innerHTML=`<h3>${T('Publications de référence','Reference publications')}</h3><ul>${(m.refs||[]).map(k=>`<li>${refs[k][0]}. <a href="${refs[k][1].startsWith('https://')?refs[k][1]:'https://doi.org/'+refs[k][1]}" target="_blank" rel="noopener noreferrer">${refs[k][1].startsWith('https://')?T('Consulter la source','View source'):'doi: '+refs[k][1]}</a></li>`).join('')}</ul>`;$('limits').textContent='';$('limits').hidden=true;if(m.reviews)$('references').innerHTML+=`<h3>${T('Synthèses de référence','Reference reviews')}</h3><ul>${m.reviews.map(k=>`<li>${refs[k][0]}. <a href="https://doi.org/${refs[k][1]}" target="_blank" rel="noopener">doi: ${refs[k][1]}</a></li>`).join('')}</ul>`;if(current==='corona')$('references').innerHTML+=proteinEvidence()+`<p><a href="#biointerfaces/fate">${T('Poursuivre : entrée et devenir cellulaire','Continue: cell entry and fate')}</a></p>`;if(current==='fate')$('references').innerHTML+=`<p>${T('Repère de dimensions : bicouche lipidique ~3–4 nm dans la source citée, sans imposer cette valeur à toutes les membranes. Le schéma est hors échelle.','Dimensional context: lipid bilayer ~3–4 nm in the cited source, not a universal value for all membranes. Diagram not to scale.')} <a href="https://bionumbers.hms.harvard.edu/bionumber.aspx?id=112585&org=&trm=membrane&ver=3" target="_blank" rel="noopener">BioNumbers BNID 112585</a>.</p>`;$('footer').textContent='NanoBioMat';draw();}
const C={teal:'#315b78',orange:'#a66b49',purple:'#775b8c',ink:'#243944'};
function line(x1,y1,x2,y2,c=C.ink,w=2,dash=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="${w}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;}
function text(x,y,s,size=17,c=C.ink){return `<text x="${x}" y="${y}" text-anchor="middle" style="font-size:${size}px;fill:${c}">${s}</text>`;}
function circle(x,y,r,fill,stroke='none',w=2){return `<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${w}"/>`;}
function arrow(x,y,a,len=50,c=C.teal,w=4){const dx=Math.sin(a)*len,dy=-Math.cos(a)*len;const ex=x+dx,ey=y+dy;return line(x-dx*.4,y-dy*.4,ex,ey,c,w)+`<path d="M ${ex-9*Math.sin(a-.55)} ${ey+9*Math.cos(a-.55)} L ${ex} ${ey} L ${ex-9*Math.sin(a+.55)} ${ey+9*Math.cos(a+.55)}" fill="none" stroke="${c}" stroke-width="${w}"/>`;}
function sphere(x,y,r,a,body=0,internal=false){let s=`<g transform="translate(${x} ${y})"><g transform="rotate(${body})">`+circle(0,0,r,'url(#vCore)','#627783',1)+line(0,-r-14,0,r+14,'#a2b2bb',1,'5 5')+`</g>`;if(internal){s+=circle(0,0,r*.82,'#f2f6f8');for(let i=0;i<24;i++){let q=i*2.399,rr=r*.66*Math.sqrt((i+.5)/24);s+=arrow(rr*Math.cos(q),rr*Math.sin(q),a+(i%2?Math.PI:0),r*(i%2?.10:.16),i%2?'#a66b49':'#315b78',1.5);}}else s+=arrow(0,0,a,r*.65,'#eef5f8',3);return s+'</g>';}

function svg(content){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 400" role="img" aria-label="${D[current].n[lang==='fr'?0:1]}">${content}</svg>`;}
function path(points,color,width=3){return `<path d="${points.map((p,i)=>(i?'L':'M')+p[0].toFixed(2)+' '+p[1].toFixed(2)).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}"/>`;}
function chart(curves,xmax,ymax,xlabel,ylabel,box=[410,80,330,240]){const[x,y,w,h]=box;let s='';for(let i=0;i<=4;i++){const px=x+w*i/4,py=y+h-h*i/4;s+=line(px,y,px,y+h,'#e3e9ed',1)+line(x,py,x+w,py,'#e3e9ed',1)+text(px,y+h+17,Number((xmax*i/4).toPrecision(3)),11,'#657b88')+text(x-19,py+4,Number((ymax*i/4).toPrecision(3)),11,'#657b88');}s+=line(x,y,x,y+h,'#586e7b',1.5)+line(x,y+h,x+w,y+h,'#586e7b',1.5)+text(x+w/2,y+h+38,xlabel,14)+text(x+w/2,y-18,ylabel,14);for(const [pts,c]of curves)s+=path(pts.map(([a,b])=>[x+w*a/xmax,y+h-h*b/ymax]),c,2.5);return s;}

// Zero-field, immobilized, noninteracting, single-barrier Néel illustration.
function drawRaw(){const m=D[current];if(m.kind==='curves')return;if(m.kind==='reading'){$('stage').innerHTML=m.body[lang==='fr'?0:1];$('math').innerHTML=EQUATIONS[current]||'';return;}const idx=Math.min(m.steps.length-1,Math.floor((current==='corona'?Math.max(0,u-1e-8):u)*m.steps.length)),step=m.steps[idx];$('timeline').value=Math.round(u*1000);$('progress').textContent=Math.round(u*100)+'%';$('steps').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',i===idx));const explanation='<h3>'+step[lang==='fr'?0:1]+'</h3><p>'+step[lang==='fr'?2:3]+'</p>'+(m.notes?'<p class="module-definitions">'+m.notes[lang==='fr'?0:1]+'</p>':'');if($('explain').innerHTML!==explanation)$('explain').innerHTML=explanation;$('math').innerHTML='';let s='';const replacement=current==='rem'?deltaScene():current==='relax'?hdrRelaxScene(u):current==='mri'?mriProjectionScene(u):current==='relaxivity'?relaxivityScene(.35):finalMagneticScene(current,u);if(replacement){$('stage').innerHTML=replacement;return;}
if(m.kind==='spin'){let a=(u<.65?-.5:-.5+(u-.65)/.35*Math.PI);s=sphere(140,195,95,a)+line(220,160,310,120,'#8c9aa0',1)+line(220,230,310,280,'#8c9aa0',1)+sphere(400,195,100,a,0,true)+arrow(560,195,Math.PI/2,30,C.ink,3)+circle(680,195,70,'#e6f2ee')+arrow(680,195,a,54,C.teal,6)+text(140,330,T('Particule monodomaine','Single-domain particle'))+text(400,330,T('Sous-réseaux couplés','Coupled sublattices'))+text(680,330,T('Moment résultant','Net moment'))+text(400,47,T('Rotation collective · opposition conservée','Collective rotation · antiparallel order preserved'),20);}
if(m.kind==='anisotropy'){const a=u*Math.PI,V=Math.PI/6*(values.d*1e-9)**3,E=values.K*1000*V,barrier=E/(1.380649e-23*values.T);s=sphere(175,190,90,a)+text(175,325,'θ = '+Math.round(u*180)+'°');const points=Array.from({length:101},(_,i)=>[i/100*180,Math.sin(i/100*Math.PI)**2]);s+=chart([[points,C.teal]],180,1,'θ (°)','E / KV')+circle(410+330*u,320-240*Math.sin(a)**2,7,C.orange)+text(410,345,'0°',13)+text(740,345,'180°',13);$('math').innerHTML=`E(θ) = KV sin²θ · ΔE = KV = ${(E/1e-21).toFixed(1)} × 10⁻²¹ J · ΔE/kBT = ${barrier.toFixed(1)}`;}
if(m.kind==='relax'){const immobilized=values.fixed||idx===2;const a=Math.PI*(.5-.5*Math.cos(4*Math.PI*u));const b=immobilized?0:Math.PI*2*u; s=text(220,48,'Néel',23)+text(585,48,T('Brown','Brownian'),23)+sphere(220,195,90,a,0,false)+sphere(585,195,90,b,b*180/Math.PI,false)+text(220,335,T('Particule fixe · moment mobile','Fixed particle · moving moment'),17)+text(585,335,immobilized?T('Rotation mécanique bloquée','Mechanical rotation blocked'):T('Particule et moment tournent','Particle and moment rotate'),17);const V=Math.PI/6*(values.d*1e-9)**3,Vh=Math.PI/6*((values.d+2*values.shell)*1e-9)**3,q=values.K*1000*V/(1.380649e-23*values.T),tn=1e-9*Math.exp(q),tb=3*values.eta*.001*Vh/(1.380649e-23*values.T);$('math').innerHTML=`τN ≈ τ₀ exp(KV/kBT) = ${tn.toExponential(2)} s · τ₀ = 10⁻⁹ s<br>τB = 3ηVh/(kBT) = ${immobilized?'∞':tb.toExponential(2)+' s'} · KV/kBT = ${q.toFixed(1)}${q<5?'<br>'+T('Barrière faible : approximation de τN à interpréter avec prudence.','Low barrier: interpret the τN approximation with caution.'):''}`;}
if(m.kind==='lamer'){const conc=t=>t<1/3?.12+1.92*t:t<2/3?.76-(t-1/3)*.99:.36*Math.exp(-4*(t-2/3))+.07;const points=Array.from({length:121},(_,i)=>[i/120,conc(i/120)]);s=chart([[points,C.teal]],1,1,T('Temps schématique','Schematic time'),T('Concentration relative','Relative concentration'),[75,65,650,230]);s+=line(75,65+230*(1-.72),725,65+230*(1-.72),C.orange,1,'6 5')+text(590,65+230*(1-.72)-10,T('Seuil de nucléation','Nucleation threshold'),14,C.orange)+circle(75+650*u,295-230*conc(u),7,C.orange);for(let i=0;i<8;i++)if(u>.32)s+=np(100+i*85,365,Math.min(19,4+Math.max(0,u-.45)*25),false);}
if(m.kind==='dipole'){const r=values.distance,a=values.angle*Math.PI/180,sep=45*r; s=circle(400-sep/2,185,34,'#d6e7e8')+circle(400+sep/2,185,34,'#d6e7e8')+arrow(400-sep/2,185,Math.PI/2,32)+arrow(400+sep/2,185,Math.PI/2+a,32,C.orange)+line(400-sep/2,260,400+sep/2,260,C.ink,2,'5 4')+text(400,292,'r = '+r.toFixed(1)+' d')+text(400,60,T('Deux moments sur un axe de séparation','Two moments on a separation axis'),21);const energy=-2*Math.cos(a)/r**3;$('math').innerHTML='Udd = μ₀/(4πr³) [m₁·m₂ − 3(m₁·r̂)(m₂·r̂)]<br>'+T('Énergie réduite pour cette géométrie : ','Reduced energy for this geometry: ')+energy.toFixed(3);s+=text(400,350,energy<-.01?T('Configuration attractive','Attractive configuration'):energy>.01?T('Configuration répulsive','Repulsive configuration'):T('Énergie dipolaire nulle ici','Zero dipolar energy here'),18);}
if(m.kind==='corona'){const phase=Math.min(1,u*2),cx=200+u*360,cy=200;s+=`<path d="M720 60 Q665 200 720 340" fill="none" stroke="#b5a0ca" stroke-width="22"/>`+text(705,365,T('Membrane','Membrane'),16)+circle(cx,cy,53,'#e0b33a');for(let i=0;i<18;i++){const a=i/18*Math.PI*2,dist=60+(1-phase)*(75+20*Math.sin(i*4));const jitter=(u>.5?7*Math.sin(u*24+i*3):0);const x=cx+Math.cos(a)*(dist+jitter),y=cy+Math.sin(a)*(dist+jitter);s+=line(cx+Math.cos(a)*50,cy+Math.sin(a)*50,cx+Math.cos(a)*59,cy+Math.sin(a)*59,'#657681',2);s+=`<ellipse cx="${x}" cy="${y}" rx="${i%2?8:12}" ry="7" fill="${i%3===0?C.orange:i%3===1?C.purple:C.teal}" transform="rotate(${a*180/Math.PI} ${x} ${y})"/>`;}s+=text(400,43,T('Milieu biologique : adsorption et échanges','Biological medium: adsorption and exchange'),21)+text(210,365,T('Identité synthétique → identité biologique','Synthetic identity → biological identity'),16);}
if(m.kind==='fate'){s=`<path d="M72 80 Q400 10 735 85 Q795 220 710 335 Q410 410 90 335 Q20 210 72 80Z" fill="#fbf5f8" stroke="#bea1b0" stroke-width="3"/>`;const regions=[[180,160,45,'#dcece6'],[350,210,60,'#d1dfe8'],[560,240,78,'#dac9e6']];for(const [x,y,r,c]of regions)s+=circle(x,y,r,c,'#7f7191',2);s+=text(180,96,T('Précoce','Early'),16)+text(350,125,T('Tardif','Late'),16)+text(560,135,T('Lysosomal','Lysosomal'),16)+text(405,375,T('Acidification progressive · durées non représentées','Progressive acidification · durations not represented'),16);let x,y,r=6;if(u<.2){x=75+u/.2*105;y=55+u/.2*105;}else if(u<.4){x=180+(u-.2)/.2*170;y=160+(u-.2)/.2*50;}else{x=u<.6?350+(u-.4)/.2*210:560;y=u<.6?210+(u-.4)/.2*30:240;}if(u>.04&&u<.6)s+=circle(x,y,29,'#dcece688','#7f7191',2);for(let i=0;i<7;i++){const a=i/7*Math.PI*2;let rad=u>.6?14+Math.min(1,(u-.6)/.2)*42:14;let pr=u>.8?Math.max(1,6*(1-(u-.8)/.2)):6;s+=circle(x+rad*Math.cos(a),y+rad*Math.sin(a),pr,C.ink);}if(u>.8){const v=(u-.8)/.2;s+=circle(697,245,22,'#fff',C.orange,3)+text(697,290,T('Ferritine','Ferritin'),15);for(let i=0;i<7;i++){const a=i*2.4;let sx=560+56*Math.cos(a),sy=240+56*Math.sin(a);s+=circle(sx+(697-sx)*v,sy+(245-sy)*v,2.5,C.orange);}s+=text(630,190,T('Fer · trajet symbolique','Iron · symbolic route'),13,C.orange);} }
if(m.kind==='mri'){const time=30*(Math.pow(101,u)-1),t1=values.T1,t2=values.T2,mz=1-Math.exp(-time/t1),mxy=Math.exp(-time/t2),blue='#0874b5',green='#00a657';
s+=text(70,35,'A',20)+text(320,35,'B',20)+line(95,260,95,90)+line(95,260,225,260)+line(95,260,55,305)+text(95,75,'z',15)+text(232,277,'y',15)+text(45,318,'x',15)+arrow(48,150,0,47,'#e5b100',5)+text(42,95,'B₀',17,'#bf9300')+arrow(202,180,Math.PI/2,25,'#92999b',6)+text(208,154,'B₁',17,'#92999b');
s+=line(95,260,95,260-130*mz,blue,4)+line(95,260,95+100*mxy,260,green,4)+line(95,260,95+100*mxy,260-130*mz,C.ink,4)+circle(95+100*mxy,260-130*mz,5,C.ink)+line(95+100*mxy,260-130*mz,95+100*mxy,260,'#98b6b7',1,'4 4')+text(60,230-120*mz,'Mz',16,blue)+text(140,288,'Mxy',16,green)+text(128,360,T('Après l’impulsion de 90°','After the 90° pulse'),15);
const ps=Array.from({length:121},(_,i)=>i*25);s+=chart([[ps.map(t=>[t,1-Math.exp(-t/t1)]),blue]],3000,1,'t (ms)','Mz / M₀',[310,75,200,210])+chart([[ps.map(t=>[t,Math.exp(-t/t2)]),green]],3000,1,'t (ms)','Mxy / M₀',[570,75,200,210]);
const y1=285-210*(1-Math.exp(-1)),y2=285-210*Math.exp(-1);s+=line(310,y1,310+200*t1/3000,y1,'#607684',1,'4 4')+line(310+200*t1/3000,y1,310+200*t1/3000,285,'#607684',1,'4 4')+text(310+200*t1/3000,338,'T₁',15,blue)+text(285,y1+5,'0.63',13,blue)+line(570,y2,570+200*t2/3000,y2,'#607684',1,'4 4')+line(570+200*t2/3000,y2,570+200*t2/3000,285,'#607684',1,'4 4')+text(570+200*t2/3000,338,'T₂',15,green)+text(545,y2+5,'0.37',13,green)+circle(310+200*time/3000,285-210*mz,5,blue)+circle(570+200*time/3000,285-210*mxy,5,green)+text(410,370,T('Relaxation longitudinale','Longitudinal relaxation'),15)+text(665,370,T('Relaxation transverse','Transverse relaxation'),15);
$('math').innerHTML='Mz(t)/M₀ = 1 − exp(−t/T₁) · Mxy(t)/M₀ = exp(−t/T₂)<br>'+T('Bleu : récupération longitudinale · vert : décroissance transverse.','Blue: longitudinal recovery · green: transverse decay.')+' · t = '+Math.round(time)+' ms · '+T('Lecture à pas de temps logarithmique','Logarithmic playback time steps');}
if(m.kind==='mpi'){const pos=100+600*u;s+=text(400,45,T('Région de champ faible en déplacement','Moving low-field region'),21)+`<rect x="100" y="100" width="600" height="110" rx="35" fill="#eef3f3"/>`+`<rect x="${pos-25}" y="85" width="50" height="140" fill="#e8c8a8" opacity=".6"/>`;for(let i=0;i<16;i++){const x=120+i*37;let a=Math.PI/2*(1+Math.tanh((x-pos)/30));s+=circle(x,155,8,C.teal)+arrow(x,155,a,27,C.ink,2);}const pts=Array.from({length:121},(_,i)=>[100+i*5,340-65/Math.cosh((100+i*5-pos)/35)**2]);s+=path(pts,C.orange)+line(100,340,700,340)+text(400,378,T('Sensibilité locale illustrative','Illustrative local sensitivity'),16);}
if(m.kind==='heat'){const p=u*2*Math.PI,h=Math.sin(p),mm=Math.sin(p-.55);s+=text(180,60,'H(t)',22)+arrow(180,195,h>=0?0:Math.PI,Math.max(1,Math.abs(h)*100),C.teal,5)+sphere(180,195,48,mm>=0?0:Math.PI)+text(180,335,T('Champ alternatif','Alternating field'),18);const points=Array.from({length:121},(_,i)=>{let t=i/120*2*Math.PI;return[575+135*Math.sin(t),195-100*Math.sin(t-.55)]});s+=line(410,195,740,195)+line(575,70,575,320)+`<path d="${points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ')}Z" fill="#a66b491b" stroke="#b8c5cc" stroke-width="1"/>`+path(points.slice(0,Math.max(2,Math.ceil(u*120))),C.orange)+circle(575+135*h,195-100*mm,7,C.teal)+text(745,220,'H',16)+text(600,70,'M',16)+text(575,360,T('Aire du cycle → dissipation','Loop area → dissipation'),18);$('math').innerHTML=T('Illustration : H = H₀ sin(ωt), M = M₀ sin(ωt − φ), φ fixé.','Illustration: H = H₀ sin(ωt), M = M₀ sin(ωt − φ), fixed φ.');}
$('stage').innerHTML=svg(s);}
$('enlarge').onclick=()=>{stop();$('zoomContent').innerHTML=$('stage').innerHTML;$('zoom').showModal();};$('closeZoom').onclick=()=>$('zoom').close();$('language').onclick=()=>{lang=lang==='fr'?'en':'fr';render();};$('timeline').oninput=e=>{stop();u=+e.target.value/1000;draw();};$('reset').onclick=()=>{stop();u=0;draw();};$('play').onclick=()=>{if(playing){stop();return;}if(u>=1)u=0;playing=true;$('play').textContent=T('Pause','Pause');u=Math.min(.995,u+.012);draw();last=performance.now();function tick(now){if(!playing)return;if(current==='corona'&&now-last<32){raf=requestAnimationFrame(tick);return;}const target=current==='corona'?Math.min(1,(Math.floor((u+1e-7)*4)+1)/4):1;u=Math.min(target,u+(now-last)/(current==='corona'?28000:current==='fate'&&u>=5/6?60000:18000));last=now;draw();if(u>=target)stop();else raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});initializeRoute();render();

function routeKeys(){return ['particles','assemblies','biointerfaces'];}
function readRoute(){
 if(typeof window==='undefined')return;
 const q=new URLSearchParams(window.location.search);
 if(q.get('lang')==='fr'||q.get('lang')==='en')lang=q.get('lang');
 const parts=window.location.hash.slice(1).split('/'),n=routeKeys().indexOf(parts[0]);if(parts[1]==='superpara')parts[1]='zfc';
 if(n>=0){axis=n;current=D[parts[1]]&&D[parts[1]].a===n?parts[1]:Object.keys(D).find(k=>D[k].a===n);}
}
function writeRoute(push=false){
 if(typeof window==='undefined')return;
 const url=new URL(window.location.href);url.searchParams.set('lang',lang);url.hash=routeKeys()[axis]+'/'+current;
 try{window.history[push?'pushState':'replaceState']({},'',url);}catch(e){}
}
function initializeRoute(){
 readRoute();
 if(typeof window!=='undefined'){window.addEventListener('popstate',()=>{readRoute();u=0;values={};render();});window.addEventListener('hashchange',()=>{readRoute();u=0;values={};render();});}
}
function chooseModule(k){
 if(!D[k])return;current=k;axis=D[k].a;u=0;values={};writeRoute(true);render();
 const content=$('content');if(content.focus)content.focus({preventScroll:true});
 if(typeof window!=='undefined'&&window.innerWidth<760)content.scrollIntoView({block:'start',behavior:'auto'});
}
function renderModuleNavigation(){
 const list=Object.keys(D).filter(k=>D[k].a===axis),i=list.indexOf(current);
 $('modulePosition').textContent=T('Module ','Module ')+(i+1)+' / '+list.length;
 $('backResearch').textContent=T('Retour à Recherche','Back to Research');
 $('backResearch').href='../'+(lang==='fr'?'fr/':'')+'research.html#'+routeKeys()[axis];
 $('moduleSelectLabel').textContent=T('Choisir une explication','Choose an explanation');
 $('moduleSelect').innerHTML=list.map(k=>'<option value="'+k+'">'+D[k].n[lang==='fr'?0:1]+'</option>').join('');
 $('moduleSelect').value=current;$('moduleSelect').onchange=e=>chooseModule(e.target.value);
 $('previousModule').textContent=T('Module précédent','Previous module');$('previousModule').disabled=i===0;
 $('nextModule').textContent=T('Module suivant','Next module');$('nextModule').disabled=i===list.length-1;
 $('previousModule').onclick=()=>chooseModule(list[i-1]);$('nextModule').onclick=()=>chooseModule(list[i+1]);
 const theme=['#31579c','#7552a0','#22786b'][axis];
 if(document.documentElement.style)document.documentElement.style.setProperty('--axis-color',theme);
 writeRoute();
}

function draw(){drawRaw();scientificTypography($('stage'));scientificTypography($('explain'));$('transport').hidden=!!D[current].static||D[current].kind==='curves';if(!EQUATIONS[current])return;let numbers='';$('math').innerHTML=EQUATIONS[current]+numbers;if(current==='monodomain')$('math').innerHTML+=T('<p>A : rigidité d’échange (J/m). K : densité d’énergie d’anisotropie (J/m³). μ₀ : perméabilité du vide. MS : aimantation à saturation (A/m).</p>','<p>A: exchange stiffness (J/m). K: anisotropy energy density (J/m³). μ₀: vacuum permeability. MS: saturation magnetization (A/m).</p>');}

function startLiveInteractions(){if(typeof performance==='undefined')return;if(current!=='interactions'||(typeof document!=='undefined'&&document.hidden))return;playing=true;last=performance.now();function next(now){if(!playing||current!=='interactions')return;advanceLivePair(values.gap??35,(now-last)/1000);last=now;draw();raf=requestAnimationFrame(next);}raf=requestAnimationFrame(next);}
const renderBeforeV414=render;render=function(){renderBeforeV414();renderPedagogy();scientificTypography(document.body);const m=D[current],reading=m.kind==='reading';for(const id of ['enlarge','steps','explain'])if(reading)$(id).hidden=true;$('transport').hidden=!!m.static||m.kind==='curves';$('limits').hidden=true;if(typeof document.querySelector==='function'){const note=document.querySelector('.figure-scroll-note');if(note)note.hidden=reading;}if(m.auto){$('steps').hidden=true;startLiveInteractions();}};
$('closeZoom').onclick=()=>{$('zoom').close();if(D[current].auto)startLiveInteractions();};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&D[current].auto)startLiveInteractions();});
render();
